import subprocess,json,sys
old="server-core-bounded-host"
stage="server-core-bounded-host-cu40-stage"
backup="server-core-bounded-host-pr299-rollback"
def step(args):
 p=subprocess.run(args,text=True,capture_output=True,timeout=25)
 if p.returncode:raise RuntimeError(args[1]+"_FAILED")
 return p.stdout.strip()
try:
 a=json.loads(step(["docker","inspect",old]))[0]
 b=json.loads(step(["docker","inspect",stage]))[0]
 if not a["State"]["Running"] or not b["State"]["Running"]:raise RuntimeError("CONTAINER_NOT_RUNNING")
 if b["Config"]["Image"]!="gace-server-core-bounded-host:cu40-0ec4261ee4e1":raise RuntimeError("IMAGE_MISMATCH")
 step(["docker","stop","-t","6",old])
 step(["docker","rename",old,backup])
 step(["docker","rename",stage,old])
 step(["docker","exec",old,"python3","-c","import urllib.request;assert urllib.request.urlopen('http://127.0.0.1:8789/healthz',timeout=3).status==200"])
 print("AGENT_POOL_RECEIVER_SWITCH=PASS")
except Exception as e:
 print("AGENT_POOL_RECEIVER_SWITCH_FAILED="+str(e)[:100])
 try:
  names=step(["docker","ps","-a","--format","{{.Names}}"]).splitlines()
  if backup in names:
   if old in names:
    subprocess.run(["docker","stop",old],capture_output=True,timeout=15)
    subprocess.run(["docker","rename",old,"server-core-bounded-host-cu40-failed"],capture_output=True,timeout=10)
   subprocess.run(["docker","rename",backup,old],capture_output=True,timeout=10)
   subprocess.run(["docker","start",old],capture_output=True,timeout=15)
 except Exception:pass
 sys.exit(1)
PY
